# Define the critical values for 95% and 99% confidence
critical_value_95 = 1.96
critical_value_99 = 2.576

# Calculate the total waste for each local area (borough and its neighbors)
local_areas = {}
for borough in df['borough'].unique():
    local_area = df[df['borough'] == borough]['Waste_value'].sum()
    local_areas[borough] = local_area

# Calculate the mean and standard deviation of the local areas
mean = np.mean(list(local_areas.values()))
std_dev = np.std(list(local_areas.values()))

# Calculate the z-score for each local area
z_scores = {}
for borough, local_area in local_areas.items():
    z = (local_area - mean) / std_dev
    z_scores[borough] = z

# Identify the hot and cold spots
hot_spots = {}
cold_spots = {}
for borough, z in z_scores.items():
    if abs(z) > critical_value_95:
        hot_spots[borough] = z
    elif abs(z) > critical_value_99:
        cold_spots[borough] = z

# Print the hot and cold spots
for borough, z in hot_spots.items():
    print(f"{borough} (HOT, z-score = {z})")
for borough, z in cold_spots.items():
    print(f"{borough} (COLD, z-score = {z})")
